 * Author: @omer-fils-elenga (https://tailwindflex.com/@omer-fils-elenga)
 * Source: https://tailwindflex.com/@omer-fils-elenga/mobil-navigation
 * Attribution: Créé par @omer-fils-elenga sur TailwindFlex
 * License: Open Source (TailwindFlex community)
 */
import React from "react";

export function MobilNavigation() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="fr">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
    <title>iOS 26 Navigation Concept</title>






    <style>
        /* --- Styles iOS 26 Personnalisés --- */
        body {
            background-color: #000;
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            overflow: hidden; /* Empêche le scroll global, on scroll dans les cartes */
        }

        /* Effet de verre ultra-avancé */
        .ios-glass {
            background: rgba(30, 30, 30, 0.4);
            backdrop-filter: blur(25px) saturate(180%);
            -webkit-backdrop-filter: blur(25px) saturate(180%);
            border: 1px solid rgba(255, 255, 255, 0.12);
            box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.37);
        }

        /* La lueur active derrière l'icône */
        .nav-indicator {
            position: absolute;
            top: 50%;
            transform: translateY(-50%) translateX(-50%);
            width: 45px;
            height: 45px;
            background: radial-gradient(circle, rgba(59,130,246,0.5) 0%, rgba(59,130,246,0) 70%);
            border-radius: 50%;
            transition: left 0.5s cubic-bezier(0.34, 1.56, 0.64, 1); /* Effet élastique */
            z-index: -1;
            filter: blur(5px);
        }

        /* --- Gestion des Pages (Fiches) --- */
        .page-card {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            padding-bottom: 100px; /* Espace pour la nav */
            overflow-y: auto;
            opacity: 0;
            transform: scale(0.95) translateY(20px);
            transition: opacity 0.4s ease, transform 0.5s cubic-bezier(0.2, 0.8, 0.2, 1);
            pointer-events: none;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            z-index: 0;
        }

        .page-card.active {
            opacity: 1;
            transform: scale(1) translateY(0);
            pointer-events: auto;
            z-index: 10;
        }

        /* Animation de sortie pour l'ancienne page */
        .page-card.exit {
            transform: scale(0.98);
            opacity: 0;
            filter: blur(10px);
        }

        /* Custom Scrollbar invisible */
        .page-card::-webkit-scrollbar {
            display: none;
        }

        /* Micro-animations des icônes */
        .nav-item ion-icon {
            transition: transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275), color 0.3s;
        }
        .nav-item.active ion-icon {
            transform: translateY(-4px) scale(1.1);
            color: #60a5fa; /* Bleu iOS */
            filter: drop-shadow(0 0 8px rgba(96, 165, 250, 0.6));
        }

    </style>
</head>
<body class="text-white h-screen w-screen relative">

    <section id="home" class="page-card active bg-gradient-to-b from-gray-900 to-black">
        <div class="w-full max-w-md p-6 space-y-6">
            <h1 class="text-5xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-purple-600">
                Bonjour.
            </h1>
            <p class="text-gray-400 text-lg">Bienvenue sur l'interface iOS 26.</p>

            <div class="w-full h-40 rounded-3xl bg-white/5 border border-white/10 p-4">
                <div class="h-full w-full bg-gradient-to-tr from-purple-500/20 to-blue-500/20 rounded-2xl flex items-center justify-center">
                    <span class="text-sm font-medium tracking-widest uppercase text-white/50">Widget Météo</span>
                </div>
            </div>
            <div class="grid grid-cols-2 gap-4">
                <div class="h-32 rounded-3xl bg-white/5 border border-white/10"></div>
                <div class="h-32 rounded-3xl bg-white/5 border border-white/10"></div>
            </div>
        </div>
    </section>

    <section id="search" class="page-card bg-gradient-to-b from-slate-900 to-black">
        <div class="w-full max-w-md p-6 flex flex-col items-center">
            <div class="w-full h-14 rounded-full bg-white/10 border border-white/10 flex items-center px-6 mb-8 backdrop-blur-md">
                <ion-icon name="search-outline" class="text-xl text-gray-400 mr-3"></ion-icon>
                <input type="text" placeholder="Rechercher..." class="bg-transparent outline-none text-white w-full placeholder-gray-500">
            </div>
            <div class="text-6xl text-gray-700 font-thin mb-4">
                <ion-icon name="planet-outline"></ion-icon>
            </div>
            <h2 class="text-2xl font-semibold">Explorer</h2>
        </div>
    </section>

    <section id="likes" class="page-card bg-gradient-to-b from-zinc-900 to-black">
        <div class="w-full max-w-md p-6">
            <h2 class="text-3xl font-bold mb-6">Activité</h2>
            <div class="space-y-4">
                <div class="flex items-center p-4 rounded-2xl bg-white/5 border border-white/10 backdrop-blur-sm">
                    <div class="w-10 h-10 rounded-full bg-blue-500 flex items-center justify-center mr-4">
                        <ion-icon name="mail" class="text-white"></ion-icon>
                    </div>
                    <div>
                        <h4 class="font-semibold">Nouveau Message</h4>
                        <p class="text-xs text-gray-400">Il y a 2 minutes</p>
                    </div>
                </div>
                <div class="flex items-center p-4 rounded-2xl bg-white/5 border border-white/10 backdrop-blur-sm">
                    <div class="w-10 h-10 rounded-full bg-green-500 flex items-center justify-center mr-4">
                        <ion-icon name="call" class="text-white"></ion-icon>
                    </div>
                    <div>
                        <h4 class="font-semibold">Appel Manqué</h4>
                        <p class="text-xs text-gray-400">Il y a 10 minutes</p>
                    </div>
                </div>
            </div>
        </div>
    </section>

    <section id="profile" class="page-card bg-gradient-to-b from-neutral-900 to-black">
        <div class="w-full max-w-md p-6 flex flex-col items-center">
            <div class="w-24 h-24 rounded-full bg-gradient-to-tr from-pink-500 to-orange-400 p-1 mb-4">
                <div class="w-full h-full rounded-full bg-gray-800 border-4 border-black"></div>
            </div>
            <h2 class="text-2xl font-bold">Utilisateur</h2>
            <p class="text-blue-400 text-sm mb-8">@ios26_concept</p>

            <button class="w-full py-4 rounded-2xl bg-white/10 border border-white/10 font-medium active:scale-95 transition-transform">
                Paramètres
            </button>
        </div>
    </section>


    <div class="fixed bottom-6 left-1/2 transform -translate-x-1/2 w-[90%] max-w-md h-20 ios-glass rounded-full flex justify-around items-center px-2 z-50">

        <div class="nav-indicator" id="indicator"></div>

        <button class="nav-item active flex flex-col items-center justify-center w-14 h-14 rounded-full text-gray-400" data-target="home">
            <ion-icon name="home-outline" class="text-2xl pointer-events-none"></ion-icon>
        </button>

        <button class="nav-item flex flex-col items-center justify-center w-14 h-14 rounded-full text-gray-400" data-target="search">
            <ion-icon name="search-outline" class="text-2xl pointer-events-none"></ion-icon>
        </button>

        <button class="nav-item flex flex-col items-center justify-center w-14 h-14 rounded-full text-gray-400" data-target="likes">
            <ion-icon name="heart-outline" class="text-2xl pointer-events-none"></ion-icon>
        </button>

        <button class="nav-item flex flex-col items-center justify-center w-14 h-14 rounded-full text-gray-400" data-target="profile">
            <ion-icon name="person-outline" class="text-2xl pointer-events-none"></ion-icon>
        </button>

    </div>


</body>
</html>" }} />
  );
}
